/* Art Deco — black and gold, geometric symmetry, sunburst elegance */
.theme-art-deco {
  --bg: oklch(0.188 0.011 80.5);
  --surface: oklch(0.220 0.014 81.6);
  --surface-2: oklch(0.256 0.020 80.3);
  --fg: oklch(0.926 0.031 88.4);
  --fg-muted: oklch(0.657 0.037 84.5);
  --accent: oklch(0.731 0.115 85.0);
  --accent-fg: oklch(0.188 0.011 80.5);
  --accent-2: oklch(0.553 0.089 82.3);
  --line: oklch(0.72 0.09 85 / 45%);
  --success: oklch(0.695 0.098 149.8);
  --warning: oklch(0.775 0.128 86.9);
  --danger: oklch(0.549 0.130 33.3);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: 0 1px 0 oklch(0.72 0.09 85 / 30%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 50%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 60%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 60%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Marcellus", Georgia, serif;
  --font-body: "Josefin Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.08em;
  --label-transform: uppercase;
  --label-tracking: 0.25em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-art-deco h1,
.theme-art-deco h2,
.theme-art-deco h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-art-deco { --font-app: var(--font-body); }

.theme-art-deco { background-image: repeating-conic-gradient(from -90deg at 50% -10%, oklch(0.72 0.09 85 / 5%) 0 4deg, transparent 4deg 12deg); }
.theme-art-deco h1 { text-transform: uppercase; letter-spacing: 0.14em; }
.theme-art-deco h1::after { content: ""; display: block; width: 4rem; margin-top: 0.6rem; border-block: 1px solid var(--accent); height: 4px; }
.theme-art-deco button { text-transform: uppercase; letter-spacing: 0.18em; outline: 1px solid var(--accent); outline-offset: 3px; }

/* depth */
.theme-art-deco thead th { font-family: var(--font-display); text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.68em; color: var(--accent); border-bottom: 1px solid var(--accent); text-align: left; }
.theme-art-deco td { border-bottom: 1px solid oklch(0.72 0.09 85 / 20%); }
.theme-art-deco tbody tr:hover { background: oklch(0.731 0.115 85.0 / 8%); }
.theme-art-deco input, .theme-art-deco select, .theme-art-deco textarea { background: transparent; border: 1px solid var(--line); border-radius: 0; color: var(--fg); }
/* physical: focus frames step outward like a ziggurat setback */
.theme-art-deco input:focus, .theme-art-deco select:focus, .theme-art-deco textarea:focus { outline: 1px solid var(--accent); outline-offset: 3px; border-color: var(--accent); box-shadow: none; }
.theme-art-deco a { color: var(--accent); text-decoration: none; letter-spacing: 0.04em; }
.theme-art-deco a:hover { text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 4px; color: oklch(0.82 0.12 88); }
.theme-art-deco kbd { font-family: var(--font-mono); font-size: 0.8em; padding: 0.12em 0.5em; border: 1px solid var(--accent-2); border-radius: 0; background: var(--surface-2); color: var(--accent); }
.theme-art-deco ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-art-deco ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-art-deco ::-webkit-scrollbar-track { background: var(--surface); }
.theme-art-deco ::-webkit-scrollbar-thumb { background: var(--accent-2); border-radius: 0; border: 2px solid var(--surface); }
.theme-art-deco ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-art-deco .label-caps { color: var(--accent); }
.theme-art-deco .label-caps::before, .theme-art-deco .label-caps::after { content: "—"; color: var(--accent-2); margin-inline: 0.5em; }
.theme-art-deco .themed-border { border: 1px solid var(--accent); outline: 1px solid oklch(0.553 0.089 82.3 / 60%); outline-offset: 4px; }
.theme-art-deco button:active { transform: translateY(1px); outline-offset: 1px; }

/* alt mode: marble lobby — cream stone, bronze inlay, sunburst in daylight */
.theme-art-deco.alt-mode {
  --bg: oklch(0.98 0.011 80.5);
  --surface: oklch(0.955 0.011 80.5);
  --surface-2: oklch(0.92 0.011 80.5);
  --fg: oklch(0.25 0.02 80);
  --fg-muted: oklch(0.48 0.035 82);
  --accent: oklch(0.54 0.11 85);
  --accent-fg: oklch(0.98 0.011 80.5);
  --accent-2: oklch(0.64 0.09 83);
  --line: oklch(0.54 0.09 85 / 40%);
  --glow: 0 0 0 1px color-mix(in oklab, oklch(0.54 0.11 85) 60%, transparent);
  --shadow-1: 0 1px 0 oklch(0.54 0.09 85 / 30%);
  --shadow-2: 0 8px 24px oklch(0.3 0.03 80 / 18%);
  --shadow-3: 0 24px 56px oklch(0.3 0.03 80 / 22%);
  background-image: repeating-conic-gradient(from -90deg at 50% -10%, oklch(0.54 0.11 85 / 7%) 0 4deg, transparent 4deg 12deg);
}
.theme-art-deco.alt-mode thead th { color: var(--accent); border-bottom-color: var(--accent); }
.theme-art-deco.alt-mode td { border-bottom-color: oklch(0.54 0.09 85 / 25%); }
.theme-art-deco.alt-mode tbody tr:hover { background: oklch(0.54 0.11 85 / 8%); }
.theme-art-deco.alt-mode a:hover { color: oklch(0.44 0.11 85); }
.theme-art-deco.alt-mode kbd { background: var(--surface-2); color: var(--accent); border-color: var(--accent-2); }
.theme-art-deco.alt-mode ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-art-deco.alt-mode ::-webkit-scrollbar-track { background: var(--surface); }
.theme-art-deco.alt-mode ::-webkit-scrollbar-thumb { background: var(--accent-2); border-color: var(--surface); }
.theme-art-deco.alt-mode h1::after { border-block-color: var(--accent); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
